INSERT INTO "RTSGrid_MetricTranslation" ("MetricId", "Locale", "DisplayName", "ShortDescription", "LongDescription", "Comparison") VALUES
    ('MonAgentNumChatsActive', 'ru-RU', 'Активные чаты (агент)', 'Число чатов, которые агент обрабатывает прямо сейчас.', 'Подсчёт в реальном времени открытых у агента чатов (одновременность чатов).', 'Завершённый аналог: MonAgentNumChatsCompleted.'),
    ('MonAgentNumChatsCompleted', 'ru-RU', 'Отвеченные чаты (агент)', 'Число входящих чатов, на которые агент ответил и завершил сегодня.', 'Считает входящие чаты, отвеченные агентом и уже завершённые.', 'Аналог в реальном времени: MonAgentNumChatsActive.'),
    ('MonAgentNumMakeCallsInCompleted', 'ru-RU', 'Отвеченные входящие звонки (агент)', 'Число входящих звонков/колбэков (callbacks), на которые агент ответил и завершил сегодня.', 'Считает входящие звонки и колбэки (callbacks), отвеченные агентом и уже завершённые (разговор окончен). ПРИМЕЧАНИЕ: в MetricId фигурирует «MakeCalls» по историческим причинам — на деле метрика считает ВХОДЯЩИЕ отвеченные обращения.', 'Незавершённые обращения исключаются до их окончания.'),
    ('MonAgentNumberOfConsultCalls', 'ru-RU', 'Консультационные звонки (агент)', 'Число консультационных звонков, совершённых агентом сегодня.', 'Накопительный счётчик переходов агента в состояние «Consulting Call» — консультация с коллегой/экспертом во время обработки обращения.', 'Частые консультации могут указывать на пробелы в знаниях или сложный трафик.'),
    ('MonAgentNumberOfInboundCalls10Min', 'ru-RU', 'Длинные звонки > 10 мин (агент)', 'Число входящих звонков, обработанных агентом со временем разговора (Talk Time) более 10 минут сегодня.', 'Считает входящие внешние звонки/колбэки (callbacks), время разговора (Talk Time) по которым превысило 600 секунд. Выделяет необычно длинные беседы для коучинга или анализа сложности.', 'Противоположный профиль: MonAgentNumberOfInboundCalls15sec.'),
    ('MonAgentNumberOfInboundCalls15sec', 'ru-RU', 'Короткие звонки < 15 сек (агент)', 'Число входящих звонков, обработанных агентом со временем разговора (Talk Time) менее 15 секунд сегодня.', 'Считает входящие внешние звонки/колбэки (callbacks), время разговора (Talk Time) по которым было менее 15 секунд. Всплеск обычно означает преждевременные разъединения или «сброс звонков» и является стандартным сигналом проблем с качеством.', 'Противоположный профиль: MonAgentNumberOfInboundCalls10Min (очень длинные звонки).'),
    ('MonAgentNumberOfInboundCallsWithIntercom', 'ru-RU', 'Входящие звонки — внешние + внутренние (агент)', 'Число входящих звонков и колбэков (callbacks), полученных агентом сегодня, внешних и внутренних.', 'Считает входящие голосовые обращения (звонки и колбэки, callbacks), обработанные агентом сегодня, включая внешние и внутренние (intercom) звонки.', 'У MonAgentNumberOfInboundCallsOnly сейчас ИДЕНТИЧНЫЙ фильтр (дубликат), хотя по названию обещаются только внешние — см. анализ дубликатов.'),
    ('MonAgentNumberOfMakeCalls', 'ru-RU', 'Исходящие звонки (агент)', 'Число исходящих внешних звонков, совершённых агентом сегодня.', 'Считает исходящие внешние голосовые звонки, инициированные агентом сегодня.', 'Групповой аналог: MonSumAgentsMakeCalls. Средняя длительность: MonAgentAverageMakeCallDuration.'),
    ('MonAgentOutgoingCallbacksNum', 'ru-RU', 'Исходящие колбэки (Callbacks) (агент)', 'Число колбэк-вызовов (callback), завершённых агентом сегодня.', 'Считает исходящие колбэк-обращения (callback) (обратные звонки клиентам), совершённые агентом и отвеченные сегодня.', 'Входящая сторона: MonAgentProxyCallsNum.'),
    ('MonAgentProxyCallsNum', 'ru-RU', 'Входящие колбэки (Callbacks) (агент)', 'Число входящих колбэк-обращений (callback), отвеченных агентом сегодня.', 'Считает входящие колбэк-обращения (callback), отвеченные агентом сегодня (без учёта самих запросов колбэка).', 'Исходящая сторона: MonAgentOutgoingCallbacksNum.'),
    ('UserCPH', 'ru-RU', 'Звонков в час (агент)', 'Входящие звонки, обработанные агентом, в час.', 'Пропускная способность на уровне агента: входящие звонки, нормированные на час работы, рассчитываются функцией CPH движка.', 'Аналог для очереди: QueueCPH.'),
    ('UserNumAllIntercom', 'ru-RU', 'Внутренние звонки (агент)', 'Число внутренних (intercom) звонков с участием агента сегодня.', 'Считает внутренние (intercom) обращения агента сегодня, в любом направлении. Нагрузка внутренней коммуникации.', NULL),
    ('UserNumMissedCalls', 'ru-RU', 'Пропущенные звонки (агент)', 'Сколько раз агент пропустил направленное ему обращение сегодня.', 'Накопительный счётчик переходов агента сегодня в состояние «Missed Call» — обращение было направлено агенту и не отвечено. Индикатор дисциплины/доступности.', 'Групповой аналог в реальном времени: MonSumAgentsInMissedCall.'),
    ('AgentMessagesAvgFirstResponseTime', 'ru-RU', 'Среднее время первого ответа — сообщения (агент)', 'Среднее время до первого ответа агента в мессенджер-беседах сегодня.', 'FRT на уровне агента: среднее время от поступления беседы до первого ответа агента (время первого ответа, First Response Time).', 'Аналог для очереди: MessagesAvgFirstResponseTime.'),
    ('AgentMessagesAvgResponseTime', 'ru-RU', 'Среднее время ответа — сообщения (агент)', 'Среднее время ответа агента на сообщения клиента сегодня.', 'Среднее время между сообщением клиента и ответом агента на уровне агента (все ответы).', 'Аналог для очереди: MessagesAvgResponseTime.'),
    ('MonAgentAvailableDuration', 'ru-RU', 'Длительность состояния Available', 'Суммарное время, проведённое агентом в состояниях группы AVAILABLE сегодня.', 'Накопительное время за сегодня в статусах группы AVAILABLE — время готовности (ожидание обращений).', 'Процент от времени в системе: MonAgentAvailableDurationPct.'),
    ('MonAgentAverageAgentDialerDuration', 'ru-RU', 'Средняя длительность звонка диалера (агент)', 'Средняя длительность звонков диалера (кампании, Dialer) агента сегодня.', 'Среднее время одного пребывания в статусе «Campaign Call» сегодня.', 'Объём диалера: MonAgentNumberOfInboundCallsDialer.'),
    ('MonAgentAverageCallDuration', 'ru-RU', 'Средняя длительность обработки (агент)', 'Средняя длительность одного пребывания агента в группе ONPHONE сегодня.', 'Среднее время одного пребывания в статусах группы ONPHONE сегодня — практический показатель времени обработки одного обращения на уровне агента.', 'Компоненты: разговор (MonAgentTalkDuration), удержание (MonAgentHeldDuration), поствызовная обработка (MonAgentWrapUpDuration).'),
    ('MonAgentAverageInboundCallDuration', 'ru-RU', 'Средняя длительность входящего звонка (агент)', 'Среднее время разговора (Talk Time) входящих звонков/колбэков (callbacks), завершённых агентом сегодня.', 'Среднее время разговора (Talk Time) завершённых входящих внешних звонков и колбэков (callbacks) агента (по обращениям, без учёта незавершённых).', 'Средняя обработка по статусам: MonAgentAverageCallDuration.'),
    ('MonAgentAverageMakeCallDuration', 'ru-RU', 'Средняя длительность исходящего звонка (агент)', 'Средняя длительность исходящих звонков агента сегодня.', 'Среднее время одного пребывания в статусе «Out Ext Call» сегодня.', 'Число исходящих: MonAgentNumberOfMakeCalls.'),
    ('MonAgentBreakDuration', 'ru-RU', 'Суммарная длительность перерывов (Break)', 'Суммарное время, проведённое агентом в состояниях группы BREAK сегодня.', 'Накопительное время за сегодня в статусах типа «перерыв» (обед, короткий перерыв и т. п.).', 'Процент от времени в системе: MonAgentBreakDurationPct. Альтернатива по одному состоянию: см. конкретные состояния.'),
    ('MonAgentCurrentLoginDuration', 'ru-RU', 'Длительность текущей сессии', 'Время с момента текущего входа агента в систему.', 'Длительность текущей сессии входа агента, отсчитывается в реальном времени.', 'Накопительный аналог: MonAgentLoginTime (все сессии за сегодня).'),
    ('MonAgentDurationOfCalls', 'ru-RU', 'Суммарная длительность входящих звонков', 'Суммарное время, проведённое агентом на входящих внешних звонках сегодня.', 'Накопительное время за сегодня в статусе «Incoming Ext Call» — входящая часть общего времени разговора (Talk Time).', 'Общее время разговора (все типы обращений): MonAgentTalkDuration.'),
    ('MonAgentDurationOfCurrentCall', 'ru-RU', 'Длительность текущего входящего звонка', 'Длительность входящего внешнего звонка, который агент обрабатывает прямо сейчас.', 'Длительность в реальном времени текущего статуса агента «Incoming Ext Call»; ноль/пусто, когда агент не на входящем внешнем звонке.', 'Максимум по группе: MonSumAgentsLongestCurrentCall.'),
    ('MonAgentHeldDuration', 'ru-RU', 'Суммарная длительность удержания (Hold)', 'Суммарное время, в течение которого агент держал клиентов на удержании (Hold) сегодня.', 'Накопительное время за сегодня в статусе «Hold». Время удержания — компонент AHT и фактор раздражения для клиента.', 'AHT = разговор + удержание + поствызовная обработка; см. MonAgentTalkDuration и MonAgentWrapUpDuration.'),
    ('MonAgentLoginTime', 'ru-RU', 'Суммарная длительность в системе', 'Суммарное время нахождения агента в системе за сегодня (все сессии).', 'Сумма всех сессий входа агента за сегодня. Знаменатель для всех метрик «процент от времени в системе».', 'Только текущая сессия: MonAgentCurrentLoginDuration.'),
    ('MonAgentMaxCallDuration', 'ru-RU', 'Макс. длительность звонка (агент)', 'Наибольшее время разговора (Talk Time) одного входящего звонка агента сегодня.', 'Максимальная длительность разговора (Talk Time) среди входящих внешних звонков/колбэков (callbacks) агента сегодня.', 'Текущий звонок в реальном времени: MonAgentDurationOfCurrentCall.'),
    ('MonAgentPaperworkDuration', 'ru-RU', 'Суммарная длительность Paperwork', 'Суммарное время, проведённое агентом в состояниях группы PAPERWORK сегодня.', 'Накопительное время за сегодня в статусах поствызовной/бэк-офисной работы (группа PAPERWORK).', 'Процент от времени в системе: MonAgentPaperworkDurationPct. Отдельное состояние Wrap Up: MonAgentWrapUpDuration.'),
    ('MonAgentStateDescDuration', 'ru-RU', 'Длительность текущей статус-группы', 'Как долго агент находится в текущей статус-группе.', 'Длительность в реальном времени пребывания агента в текущей статус-группе: переключение между состояниями внутри одной группы (например, Lunch → Coffee Break) не сбрасывает этот таймер.', 'Таймер на уровне состояния: MonAgentStateDuration.'),
    ('MonAgentStateDuration', 'ru-RU', 'Длительность текущего статуса', 'Как долго агент находится в текущем статусе.', 'Длительность в реальном времени текущего статуса агента, каким бы он ни был. Универсальная колонка-таймер для вол-борда.', 'Длительность текущей статус-группы: MonAgentStateDescDuration.'),
    ('MonAgentTalkDuration', 'ru-RU', 'Суммарная длительность разговора (Talk Time)', 'Суммарное время, проведённое агентом в состояниях группы ONPHONE сегодня.', 'Сумма всего времени за сегодня в статусах группы ONPHONE — общее время разговора (Talk Time) с клиентами.', 'Процент от времени в системе: MonAgentTalkDurationPct. Среднее на звонок: MonAgentAverageCallDuration.'),
    ('MonAgentTelStateDuration', 'ru-RU', 'Длительность состояния активного обращения', 'Как долго самое длинное активное обращение агента находится в своём текущем состоянии.', 'Длительность в реальном времени текущего состояния (например, разговор, удержание/Hold) самого длинного активного обращения агента.', 'Само состояние обращения: MonAgentTelState.'),
    ('MonAgentUnavailableStateDuration', 'ru-RU', 'Суммарная длительность Unavailable', 'Суммарное время, проведённое агентом в состоянии «Unavailable» сегодня.', 'Накопительное время за сегодня в конкретном статусе «Unavailable».', NULL),
    ('MonAgentWrapUpDuration', 'ru-RU', 'Суммарная длительность Wrap Up', 'Суммарное время, проведённое агентом в состоянии «Wrap Up» сегодня.', 'Накопительное время за сегодня в конкретном статусе «Wrap Up» (одно из состояний группы PAPERWORK).', 'Поствызовная обработка (Wrap Up / ACW) по всей группе: MonAgentPaperworkDuration.'),
    ('AgentLoginName', 'ru-RU', 'Логин (имя)', 'Отображаемое имя / логин агента.', 'Статический атрибут, используемый как подпись строки в виджетах Agent Grid.', NULL),
    ('MonActiveCampaign', 'ru-RU', 'Очередь активного обращения', 'Имя очереди (рабочей группы) самого длинного активного обращения агента.', 'Атрибут в реальном времени: из какой очереди поступило самое длинное активное обращение.', NULL),
    ('MonAgentActiveInteractionId', 'ru-RU', 'ID активного обращения', 'Идентификатор самого длинного активного обращения агента.', 'Атрибут в реальном времени: ID самого длинного активного обращения агента в данный момент.', 'Сопутствующие: тип, состояние, очередь, номер клиента того же обращения.'),
    ('MonAgentCurrentLoginTimeStamp', 'ru-RU', 'Время текущего входа', 'Отметка времени текущего входа агента в систему.', 'Атрибут: время начала текущей сессии входа.', NULL),
    ('MonAgentExtension', 'ru-RU', 'Внутренний номер (Extension)', 'Телефонный внутренний номер агента.', 'Статический атрибут: внутренний номер (extension) агента.', NULL),
    ('MonAgentFirstLoginTimeStamp', 'ru-RU', 'Время первого входа', 'Отметка времени первого входа агента сегодня.', 'Атрибут, статичный в пределах дня: когда агент впервые вошёл в систему сегодня.', 'Начало текущей сессии: MonAgentCurrentLoginTimeStamp.'),
    ('MonAgentState', 'ru-RU', 'Текущий статус', 'Название текущего статуса агента.', 'Текстовый атрибут в реальном времени: заголовок текущего состояния агента (Agent State), например Available, Lunch, Wrap Up.', 'Имя группы: MonAgentStateDesc. Таймер: MonAgentStateDuration.'),
    ('MonAgentStateDesc', 'ru-RU', 'Текущая статус-группа', 'Статус-группа текущего статуса агента.', 'Текстовый атрибут в реальном времени: статус-группа (AVAILABLE / ONPHONE / BREAK / PAPERWORK / TRAINING) текущего состояния агента.', 'Имя состояния: MonAgentState.'),
    ('MonAgentStation', 'ru-RU', 'ID рабочего места (Station)', 'Идентификатор рабочего места / телефонной станции агента.', 'Статический атрибут: рабочее место (station), на котором агент вошёл в систему.', NULL),
    ('MonAgentTelState', 'ru-RU', 'Состояние активного обращения', 'Состояние самого длинного активного обращения агента.', 'Атрибут в реальном времени: текущее состояние (например, разговор, удержание/Hold) самого длинного активного обращения.', 'Длительность этого состояния: MonAgentTelStateDuration.'),
    ('MonAgentTodayLogin', 'ru-RU', 'Входил сегодня (флаг)', 'Флаг/ID, указывающий, что агент входил в систему сегодня.', 'Технический атрибут, отмечающий агентов, подключавшихся в течение текущего дня. ПРИМЕЧАНИЕ: его описание в БД («Change -ID of a representative...») не имеет стандартного префикса «Agent -» и требует нормализации.', NULL),
    ('MonAgentUserId', 'ru-RU', 'ID пользователя (User ID)', 'Идентификатор пользователя агента на платформе.', 'Статический атрибут: User ID агента на CC-платформе.', NULL),
    ('MonInteractionType', 'ru-RU', 'Тип активного обращения', 'Тип (звонок/чат/...) самого длинного активного обращения агента.', 'Атрибут в реальном времени: тип самого длинного активного обращения.', NULL),
    ('RemotePhoneNumber', 'ru-RU', 'Номер телефона клиента', 'Номер телефона клиента в самом длинном активном обращении агента.', 'Атрибут в реальном времени: номер удалённой стороны самого длинного активного обращения. Содержит ПДн (PII) — применяйте маскирование, где требуется.', NULL),
    ('MonAgentAvailableDurationPct', 'ru-RU', '% времени Available от входа', 'Доля времени агента в системе, проведённая в состояниях AVAILABLE сегодня.', 'Накопительное время группы AVAILABLE, делённое на общее время в системе, — доля готовности.', 'Высокий % Available + низкий % разговора = недозагрузка; обратное указывает на перегрузку.'),
    ('MonAgentBreakDurationPct', 'ru-RU', '% времени Break от входа', 'Доля времени агента в системе, проведённая в состояниях BREAK сегодня.', 'Накопительное время группы BREAK, делённое на общее время в системе, — потери на перерывы (shrinkage) на агента.', 'Групповой аналог: MonSumAgentsBreakDurationPercent.'),
    ('MonAgentPaperworkDurationPct', 'ru-RU', '% времени Paperwork от входа', 'Доля времени агента в системе, проведённая в состояниях PAPERWORK сегодня.', 'Накопительное время группы PAPERWORK, делённое на общее время в системе, — доля поствызовной обработки (ACW).', 'Групповой аналог: MonSumAgentsPaperworkDurationPercent.'),
    ('MonAgentTalkDurationPct', 'ru-RU', '% времени разговора от входа', 'Доля времени агента в системе, проведённая в состояниях ONPHONE сегодня.', 'Накопительное время группы ONPHONE, делённое на общее время в системе. Практический показатель загрузки (Occupancy) на агента (по разговору; без поствызовной обработки).', 'Сопутствующие: % Available, % Break, % Paperwork, % Training.'),
    ('MonAgentTrainingDurationPct', 'ru-RU', '% времени Training от входа', 'Доля времени агента в системе, проведённая в состояниях TRAINING сегодня.', 'Накопительное время группы TRAINING, делённое на общее время в системе.', NULL),
    ('MonSumAgentsBreakDurationMax', 'ru-RU', 'Макс. текущая длительность перерыва (группа)', 'Наибольшее время, которое любой агент группы сейчас находится в состоянии группы Break.', 'Максимум в реальном времени: среди агентов, находящихся сейчас в состоянии группы BREAK, длительность самого долгого текущего перерыва. Выделяет затянувшиеся перерывы на вол-бордах.', 'Процентный аналог: MonSumAgentsBreakDurationPercent.'),
    ('MonSumAgentsBreakDurationPercent', 'ru-RU', '% времени в группе Break (группа)', 'Доля времени группы в системе, проведённая в состояниях группы Break.', 'Накопительный процент за сегодня: суммарное время агентов бизнес-юнита (BU) в состояниях группы BREAK, делённое на их общее время в системе. Ключевой индикатор потерь (shrinkage).', 'Аналог на уровне агента: MonAgentBreakDurationPct.'),
    ('MonSumAgentsPaperworkDurationPercent', 'ru-RU', '% времени в группе Paperwork (группа)', 'Доля времени группы в системе, проведённая в состояниях группы Paperwork.', 'Накопительный процент за сегодня: суммарное время группы PAPERWORK, делённое на общее время группы в системе. Измеряет нагрузку поствызовной обработки (Wrap Up / ACW) / бэк-офиса.', 'Аналог на уровне агента: MonAgentPaperworkDurationPct.'),
    ('MonAgentNumberOfInboundCallsDialer', 'ru-RU', 'Звонки диалера (Dialer)', 'Число входящих обращений диалера (кампании, Dialer) сегодня.', 'Считает обращения типа Dialer (звонки исходящей кампании, доставляемые агентам как входящие), зарегистрированные сегодня, внешние или внутренние (intercom). ПРИМЕЧАНИЕ: префикс описания указывает «Agent Group», тогда как DataType — «User»; движок сопоставляет DataType, отличный от «UsersInteraction», с набором обращений очереди, поэтому метрика ведёт себя как счётчик уровня очереди.', 'Аналог средней длительности: MonAgentAverageAgentDialerDuration.'),
    ('MonSumAgentsAnsweredCalls', 'ru-RU', 'Отвеченные звонки + колбэки (группа)', 'Число входящих звонков и колбэков (callbacks), отвеченных и завершённых агентами этой группы сегодня.', 'Считает входящие внешние звонки и колбэки (callbacks), которые агенты бизнес-юнита (BU) ответили и уже завершили (разговор окончен, больше не в очереди). Рассчитывается по набору обращений группы агентов (UsersInteraction).', 'Почти эквивалент со стороны очереди: QueueNumAnsweredCallsAndCallbacks (считается при ответе, включает незавершённые).'),
    ('MonSumAgentsAverageCallDuration', 'ru-RU', 'Среднее время разговора — звонки+колбэки (группа)', 'Среднее время разговора (Talk Time) входящих звонков и колбэков (callbacks), завершённых этой группой сегодня.', 'Среднее время беседы по входящим внешним звонкам и колбэкам (callbacks), завершённым сегодня агентами бизнес-юнита (BU), рассчитанное по набору обращений группы агентов.', 'Аналог со стороны очереди: QueueAvgTalkingDurationCallsAndCallbacks.'),
    ('MonSumAgentsAverageChatDuration', 'ru-RU', 'Среднее время обработки — чаты (группа)', 'Средняя длительность обработки входящих чатов, завершённых этой группой сегодня.', 'Среднее время обработки входящих чатов, завершённых сегодня агентами бизнес-юнита (BU) (набор обращений группы агентов).', 'Аналог со стороны очереди: QueueAvgTalkingDurationChats.'),
    ('MonSumAgentsLongestCurrentCall', 'ru-RU', 'Самый длинный текущий звонок (группа)', 'Длительность самого длинного обращения, обрабатываемого сейчас агентом этой группы.', 'Максимальная длительность разговора (Talk Time) в реальном времени среди обращений, обрабатываемых сейчас в бизнес-юните (BU). Выделяет необычно затянувшиеся беседы.', 'Аналог на уровне агента: MonAgentDurationOfCurrentCall.'),
    ('MonSumAgentsMakeCalls', 'ru-RU', 'Исходящие звонки (группа)', 'Число исходящих внешних обращений, совершённых агентами этой группы сегодня.', 'Считает исходящие внешние обращения, инициированные агентами бизнес-юнита (BU) сегодня (рассчитывается по набору обращений группы агентов).', 'Аналог со стороны очереди: QueueNumOutboundCalls. На уровне агента: MonAgentNumberOfMakeCalls.'),
    ('MonSumAgentsInMissedCall', 'ru-RU', 'Агенты в состоянии «Missed Call»', 'Число агентов, находящихся сейчас в состоянии «Missed Call».', 'Счётчик в реальном времени агентов, чьё текущее состояние — «Missed Call» (состояние, в которое агент попадает после неответа на направленное обращение). Стабильно ненулевые значения сигнализируют о проблемах маршрутизации или дисциплины.', 'Накопительный аналог на уровне агента: UserNumMissedCalls.'),
    ('StateCountAvailable', 'ru-RU', 'Агенты в состоянии «Available»', 'Число агентов, находящихся сейчас именно в состоянии «Available».', 'Счётчик в реальном времени агентов, чьё текущее состояние (Agent State) — ровно «Available». Считает «сырое» состояние платформы, а не статус-группу: пользовательские состояния, отнесённые к группе AVAILABLE (например, «Ready-Chat»), НЕ включаются.', 'Аналог на уровне группы: QueueLoginDataNumAvailableUsers.'),
    ('StateCountBreak', 'ru-RU', 'Агенты в состоянии «Break»', 'Число агентов, находящихся сейчас именно в состоянии «Break».', 'Счётчик в реальном времени агентов, чьё текущее состояние (Agent State) — ровно «Break». Состояния вроде «Lunch» или «Coffee Break» не включаются, хотя относятся к группе BREAK.', 'Аналог на уровне группы: QueueLoginDataNumBreakUsers.'),
    ('StateCountOnPhone', 'ru-RU', 'Агенты в состоянии «On Phone»', 'Число агентов, находящихся сейчас именно в состоянии «On Phone».', 'Счётчик в реальном времени агентов, чьё текущее состояние (Agent State) — ровно «On Phone» («сырое» состояние, а не группа ONPHONE).', 'Аналог на уровне группы: UsersSumOnCall.'),
    ('StateCountPaperwork', 'ru-RU', 'Агенты в состоянии «Paperwork»', 'Число агентов, находящихся сейчас именно в состоянии «Paperwork».', 'Счётчик в реальном времени агентов, чьё текущее состояние (Agent State) — ровно «Paperwork» («сырое» состояние, а не группа PAPERWORK).', 'Аналог на уровне группы: QueueLoginDataNumPaperworkUsers.'),
    ('StateCountTraining', 'ru-RU', 'Агенты в состоянии «Training»', 'Число агентов, находящихся сейчас именно в состоянии «Training».', 'Счётчик в реальном времени агентов, чьё текущее состояние (Agent State) — ровно «Training» («сырое» состояние, а не группа TRAINING).', 'Аналог на уровне группы: QueueLoginDataNumTrainingUsers.'),
    ('QueueLoginDataNumAvailableUsers', 'ru-RU', 'Агенты Available (группа)', 'Число агентов, находящихся сейчас в статус-группе AVAILABLE.', 'Счётчик в реальном времени агентов бизнес-юнита (BU), чей текущий статус относится к статус-группе AVAILABLE (готовы принять обращение).', 'StateCountAvailable считает только конкретное состояние «Available»; эта метрика считает всю группу.'),
    ('QueueLoginDataNumBreakUsers', 'ru-RU', 'Агенты в группе Break', 'Число агентов, находящихся сейчас в любом состоянии группы Break.', 'Счётчик в реальном времени агентов, чей текущий статус относится к статус-группе BREAK (обед, короткий перерыв, кофе-брейк и т. п.).', 'StateCountBreak считает только конкретное состояние «Break»; эта метрика охватывает все состояния типа «перерыв».'),
    ('QueueLoginDataNumLoggedUsers', 'ru-RU', 'Агенты в системе', 'Число агентов бизнес-юнита (BU), находящихся сейчас в системе.', 'Счётчик в реальном времени агентов, вошедших сейчас на платформу в рамках этого бизнес-юнита (BU), в любом статусе. Базис для оценки укомплектованности и загрузки (Occupancy).', 'QueueNumberOfLoggedAgents — его (устаревший) дубликат. Счётчики Available/Break/Paperwork являются подмножествами.'),
    ('QueueLoginDataNumPaperworkUsers', 'ru-RU', 'Агенты в группе Paperwork', 'Число агентов, находящихся сейчас в любом состоянии группы Paperwork (ACW/бэк-офис).', 'Счётчик в реальном времени агентов, чей текущий статус относится к статус-группе PAPERWORK (поствызовная обработка, административные задачи).', 'QueueNumWrapUpAgents считает только единственное состояние «Wrap Up».'),
    ('QueueLoginDataNumTrainingUsers', 'ru-RU', 'Агенты в группе Training', 'Число агентов, находящихся сейчас в любом состоянии группы Training.', 'Счётчик в реальном времени агентов, чей текущий статус относится к статус-группе TRAINING. ПРИМЕЧАНИЕ: эта строка несёт аномальный DataType («String» вместо «UsersSummary») и пустые колонки по умолчанию — для движка безвредно (DataType игнорируется для счётчиков статусов), но требует нормализации.', 'StateCountTraining считает только конкретное состояние «Training».'),
    ('UsersSumOnCall', 'ru-RU', 'Агенты на обращении', 'Число агентов, находящихся сейчас в статус-группе ONPHONE (обрабатывают обращение).', 'Счётчик в реальном времени агентов, чей текущий статус относится к группе ONPHONE — активно обрабатывают обращения клиентов.', 'QueueNumOnCallAgents — его (устаревший) дубликат. StateCountOnPhone считает только конкретное состояние.'),
    ('QueueAvgTimeToAbandCallbacks', 'ru-RU', 'Среднее время до отказа — Колбэки (Callbacks)', 'Среднее время, которое входящие колбэк-обращений (callback) ждали в очереди до того, как были потеряны (abandoned), сегодня.', 'Среднее время в очереди для потерянных (abandoned) входящих колбэк-обращений (callback): сколько клиенты были готовы ждать, прежде чем отказаться. Полезно для постановки реалистичных целей по уровню сервиса (Service Level) — если клиенты отказываются на 40-й секунде, цель в 60 секунд слишком медленная.', 'Подмножество «Среднего времени ожидания», ограниченное потерянными обращениями.'),
    ('QueueAvgTimeToAbandCalls', 'ru-RU', 'Среднее время до отказа — Звонки', 'Среднее время, которое входящие внешних голосовых звонков ждали в очереди до того, как были потеряны (abandoned), сегодня.', 'Среднее время в очереди для потерянных (abandoned) входящих внешних голосовых звонков: сколько клиенты были готовы ждать, прежде чем отказаться. Полезно для постановки реалистичных целей по уровню сервиса (Service Level) — если клиенты отказываются на 40-й секунде, цель в 60 секунд слишком медленная.', 'Подмножество «Среднего времени ожидания», ограниченное потерянными обращениями.'),
    ('QueueAvgTimeToAbandCallsAndCallbacks', 'ru-RU', 'Среднее время до отказа — Звонки и колбэки', 'Среднее время, которое входящие звонков и колбэков (внешняя голосовая нагрузка) ждали в очереди до того, как были потеряны (abandoned), сегодня.', 'Среднее время в очереди для потерянных (abandoned) входящих звонков и колбэков (внешняя голосовая нагрузка): сколько клиенты были готовы ждать, прежде чем отказаться. Полезно для постановки реалистичных целей по уровню сервиса (Service Level) — если клиенты отказываются на 40-й секунде, цель в 60 секунд слишком медленная.', 'Подмножество «Среднего времени ожидания», ограниченное потерянными обращениями.'),
    ('QueueAvgTimeToAbandChats', 'ru-RU', 'Среднее время до отказа — Чаты', 'Среднее время, которое входящие чатов ждали в очереди до того, как были потеряны (abandoned), сегодня.', 'Среднее время в очереди для потерянных (abandoned) входящих чатов: сколько клиенты были готовы ждать, прежде чем отказаться. Полезно для постановки реалистичных целей по уровню сервиса (Service Level) — если клиенты отказываются на 40-й секунде, цель в 60 секунд слишком медленная.', 'Подмножество «Среднего времени ожидания», ограниченное потерянными обращениями.'),
    ('QueueAvgTimeToAbandInteractions', 'ru-RU', 'Среднее время до отказа — Цифровые обращения', 'Среднее время, которое входящие цифровых обращений (chat и e-mail) ждали в очереди до того, как были потеряны (abandoned), сегодня.', 'Среднее время в очереди для потерянных (abandoned) входящих цифровых обращений (chat и e-mail): сколько клиенты были готовы ждать, прежде чем отказаться. Полезно для постановки реалистичных целей по уровню сервиса (Service Level) — если клиенты отказываются на 40-й секунде, цель в 60 секунд слишком медленная.', 'Подмножество «Среднего времени ожидания», ограниченное потерянными обращениями.'),
    ('MessagesAvgFirstResponseTime', 'ru-RU', 'Среднее время первого ответа (сообщения)', 'Среднее время до первого ответа агента в мессенджер-каналах сегодня.', 'Среднее время между поступлением сообщения и первым ответом агента. Ключевой KPI отзывчивости (время первого ответа, First Response Time) для каналов чат/мессенджер.', 'MessagesAvgResponseTime охватывает ВСЕ ответы, а не только первый.'),
    ('MessagesAvgResponseTime', 'ru-RU', 'Среднее время ответа (сообщения)', 'Среднее время ответа агента на сообщения клиента сегодня (все ответы).', 'Среднее время между любым сообщением клиента и следующим ответом агента. Измеряет устойчивую отзывчивость в беседе, а не только первый контакт.', 'MessagesAvgFirstResponseTime выделяет только первый ответ.'),
    ('MessagesMaxFirstResponseTime', 'ru-RU', 'Макс. время первого ответа (сообщения)', 'Наибольшее время первого ответа на входящее сообщение сегодня.', 'Максимальное время, которое клиенты ждали сегодня ПЕРВОГО ответа агента в мессенджер-каналах. Индикатор наихудшего случая цифровой отзывчивости.', 'Средний аналог: MessagesAvgFirstResponseTime.'),
    ('QueuePctAbandonedCallbacksTotal', 'ru-RU', '% потерянных колбэков (Callbacks)', 'Доля входящих колбэк-обращений (callback), потерянных (abandoned) в очереди, от всех завершивших ожидание сегодня.', 'Потерянные (abandoned) входящие колбэк-обращений (callback), делённые на входящие завершённые колбэк-обращений (callback). Стандартный KPI доли потерянных (Abandonment Rate) — прямая мера клиентов, потерянных в очереди. Запросы колбэка (callback) потерянными не считаются.', 'Дополняет показатель «% отвеченных».'),
    ('QueuePctAbandonedCallsTotal', 'ru-RU', '% потерянных звонков', 'Доля входящих внешних голосовых звонков, потерянных (abandoned) в очереди, от всех завершивших ожидание сегодня.', 'Потерянные (abandoned) входящие внешних голосовых звонков, делённые на входящие завершённые внешних голосовых звонков. Стандартный KPI доли потерянных (Abandonment Rate) — прямая мера клиентов, потерянных в очереди. Запросы колбэка (callback) потерянными не считаются.', 'Дополняет показатель «% отвеченных».'),
    ('QueuePctAbandonedCallsAndCallbacksTotal', 'ru-RU', '% потерянных звонков и колбэков', 'Доля входящих звонков и колбэков (внешняя голосовая нагрузка), потерянных (abandoned) в очереди, от всех завершивших ожидание сегодня.', 'Потерянные (abandoned) входящие звонков и колбэков (внешняя голосовая нагрузка), делённые на входящие завершённые звонков и колбэков (внешняя голосовая нагрузка). Стандартный KPI доли потерянных (Abandonment Rate) — прямая мера клиентов, потерянных в очереди. Запросы колбэка (callback) потерянными не считаются.', 'Дополняет показатель «% отвеченных».'),
    ('QueuePctAbandonedChatsTotal', 'ru-RU', '% потерянных чатов', 'Доля входящих чатов, потерянных (abandoned) в очереди, от всех завершивших ожидание сегодня.', 'Потерянные (abandoned) входящие чатов, делённые на входящие завершённые чатов. Стандартный KPI доли потерянных (Abandonment Rate) — прямая мера клиентов, потерянных в очереди. Запросы колбэка (callback) потерянными не считаются.', 'Дополняет показатель «% отвеченных».'),
    ('QueuePctAbandonedInteractionsTotal', 'ru-RU', '% потерянных цифровых обращений', 'Доля входящих цифровых обращений (chat и e-mail), потерянных (abandoned) в очереди, от всех завершивших ожидание сегодня.', 'Потерянные (abandoned) входящие цифровых обращений (chat и e-mail), делённые на входящие завершённые цифровых обращений (chat и e-mail). Стандартный KPI доли потерянных (Abandonment Rate) — прямая мера клиентов, потерянных в очереди. Запросы колбэка (callback) потерянными не считаются.', 'Дополняет показатель «% отвеченных».'),
    ('QueuePctAnsweredCallbacks30secAns', 'ru-RU', '% отвеченных колбэков (Callbacks) за 30 сек (от отвеченных)', 'Доля отвеченных колбэк-обращений (callback), принятых в течение 30 сек.', 'Входящие колбэк-обращений (callback), отвеченные в течение 30 сек, делённые на все отвеченные колбэк-обращений (callback). Отражает только профиль скорости по отвеченным обращениям: какая доля принятых обращений была обработана быстро. Потерянные обращения полностью игнорируются.', 'Всегда ≥ варианта «…от входящих» (уровень сервиса, Service Level). Для отчётности по SLA используйте вариант «от входящих»; этот — для анализа скорости ответа.'),
